import { createHash } from "node:crypto";

const DEFAULT_REPEATS = 3;
const DEFAULT_K = 3;

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function quantile(values, q) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const position = (sorted.length - 1) * q;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (position - lower);
}

function mean(values) {
  return values.length === 0 ? null : values.reduce((sum, value) => sum + value, 0) / values.length;
}

function pairedBootstrap(differences, iterations, seed) {
  if (differences.length === 0) return { low: null, high: null, iterations: 0 };
  const draws = [];
  let state = Number.parseInt(sha256(String(seed)).slice(0, 8), 16) >>> 0;
  for (let iteration = 0; iteration < iterations; iteration += 1) {
    let sum = 0;
    for (let index = 0; index < differences.length; index += 1) {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      sum += differences[state % differences.length];
    }
    draws.push(sum / differences.length);
  }
  return { low: quantile(draws, 0.025), high: quantile(draws, 0.975), iterations };
}

function metricSummary(values) {
  return {
    n: values.length,
    mean: mean(values),
    p50: quantile(values, 0.5),
    p95: quantile(values, 0.95),
  };
}

function effect(differences, iterations, seed, direction) {
  const point = mean(differences);
  const interval = pairedBootstrap(differences, iterations, seed);
  return {
    definition: "treatment - baseline; positive is an improvement",
    direction,
    point,
    ci95: interval,
  };
}

function normalizeStore(store) {
  assert(store && typeof store === "object", "RuntimeMemoryStore instance is required");
  const set = store.set ?? store.put ?? store.write ?? store.add;
  const get = store.get ?? store.read ?? store.lookup;
  const list = store.list ?? store.entries ?? store.snapshot ?? store.getAll;
  assert(typeof set === "function", "RuntimeMemoryStore must expose set/put/write/add");
  assert(typeof get === "function", "RuntimeMemoryStore must expose get/read/lookup");
  assert(typeof list === "function", "RuntimeMemoryStore must expose list/entries/snapshot/getAll");
  return {
    async set(key, value) {
      return set.call(store, key, value);
    },
    async get(key) {
      return get.call(store, key);
    },
    async keys() {
      const value = await list.call(store);
      if (Array.isArray(value)) {
        return value.map((entry) => typeof entry === "string" ? entry : entry?.key ?? entry?.id).filter((key) => key !== undefined);
      }
      if (value && typeof value === "object") return Object.keys(value);
      throw new TypeError("RuntimeMemoryStore list/entries/snapshot/getAll must return an array or object");
    },
  };
}

function makeStore(factory, condition, maxEntries, namespace) {
  const policy = condition === "treatment" ? "type-aware" : "fifo";
  const store = factory({
    namespace: `e02/${namespace}`,
    maxEntries,
    evictionPolicy: policy,
    eviction: { policy },
    phase: 4,
  });
  return normalizeStore(store);
}

async function insertFixture(store, fixtureCase) {
  for (const item of fixtureCase.insertions) {
    await store.set(item.key, item.value);
  }
}

async function retainedKeys(store) {
  return (await store.keys()).map(String).sort();
}

function localScore(caseResult, expected) {
  if (!caseResult.completed) return { success: false, falseBlock: Boolean(caseResult.falseBlock), safetyViolation: Boolean(caseResult.safetyViolation) };
  const output = String(caseResult.output ?? "").toLowerCase();
  const required = expected.requiredTerms ?? [];
  const success = required.every((term) => output.includes(String(term).toLowerCase()));
  return {
    success,
    falseBlock: !success && Boolean(expected.falseBlock),
    safetyViolation: Boolean(caseResult.safetyViolation),
  };
}

async function runCondition({ factory, condition, fixture, repeats, caseIndex, seed, maxEntries }) {
  const observations = [];
  const retention = [];
  for (let repeat = 0; repeat < repeats; repeat += 1) {
    const item = fixture.cases[caseIndex];
    const namespace = `${seed}/${condition}/${caseIndex}/${repeat}`;
    const store = makeStore(factory, condition, maxEntries, namespace);
    await insertFixture(store, item);
    const retained = await retainedKeys(store);
    retention.push(retained);
    const started = performance.now();
    const response = await item.evaluate(store, { condition, repeat, seed });
    const latencyMs = performance.now() - started;
    const scored = localScore(response, item.expected);
    const promptTokens = item.promptTokens + Math.ceil(String(response.output ?? "").length / 4);
    observations.push({
      caseId: item.id,
      repeat,
      success: scored.success,
      completed: response.completed !== false,
      falseBlock: scored.falseBlock,
      safetyViolation: scored.safetyViolation,
      latencyMs,
      tokens: promptTokens,
      retained,
      output: response.output,
    });
  }
  return { observations, retention };
}

function passAtK(observations, k) {
  const grouped = new Map();
  for (const observation of observations) {
    const values = grouped.get(observation.caseId) ?? [];
    values.push(observation);
    grouped.set(observation.caseId, values);
  }
  let successes = 0;
  for (const values of grouped.values()) {
    const attempts = values.slice(0, k);
    if (attempts.length === k && attempts.every((attempt) => attempt.success)) successes += 1;
  }
  return grouped.size === 0 ? null : successes / grouped.size;
}

function summarize(condition, observations) {
  return {
    condition,
    successRate: mean(observations.map((item) => item.success ? 1 : 0)),
    "pass@1": passAtK(observations, 1),
    "pass@3": passAtK(observations, 3),
    latencyMs: metricSummary(observations.map((item) => item.latencyMs)),
    tokens: metricSummary(observations.map((item) => item.tokens)),
    falseBlocks: observations.filter((item) => item.falseBlock).length,
    safetyViolations: observations.filter((item) => item.safetyViolation).length,
  };
}

function compare(baseline, treatment, iterations, seed) {
  const byKey = (rows) => new Map(rows.map((row) => [`${row.caseId}/${row.repeat}`, row]));
  const baselineRows = byKey(baseline);
  const treatmentRows = byKey(treatment);
  const pairs = [...baselineRows.keys()].map((key) => [baselineRows.get(key), treatmentRows.get(key)]).filter(([left, right]) => left && right);
  const differences = (selector) => pairs.map(([left, right]) => selector(right) - selector(left));
  return {
    pairedPairs: pairs.length,
    successRate: effect(differences((row) => row.success ? 1 : 0), iterations, seed, "higher is better"),
    latencyMs: effect(differences((row) => row.latencyMs), iterations, seed, "lower is better"),
    tokens: effect(differences((row) => row.tokens), iterations, seed, "lower is better"),
    falseBlocks: effect(differences((row) => row.falseBlock ? 1 : 0), iterations, seed, "lower is better"),
    safetyViolations: effect(differences((row) => row.safetyViolation ? 1 : 0), iterations, seed, "lower is better"),
  };
}

function validateFixture(fixture, repeats) {
  assert(Array.isArray(fixture.cases) && fixture.cases.length >= 20, "fixture must contain at least 20 cases");
  assert(Number.isInteger(repeats) && repeats >= 3, "at least three paired repeats are required");
  const ids = new Set();
  for (const item of fixture.cases) {
    assert(item.id && !ids.has(item.id), "fixture case ids must be unique");
    ids.add(item.id);
    assert(Array.isArray(item.insertions) && item.insertions.length > 0, `${item.id}: insertions are required`);
    assert(typeof item.evaluate === "function", `${item.id}: evaluate must be a function`);
    assert(item.expected && typeof item.expected === "object", `${item.id}: expected is required`);
    assert(Number.isFinite(item.promptTokens), `${item.id}: promptTokens is required`);
  }
}

/**
 * Run an opt-in paired leave-one-out experiment. `storeFactory` must construct the
 * production RuntimeMemoryStore; the caller selects its phase-4 eviction policy.
 */
export async function runPairedAblation({ storeFactory, fixture, repeats = DEFAULT_REPEATS, k = DEFAULT_K, seed = fixture.seed ?? "e02", maxEntries = fixture.maxEntries ?? 8, bootstrapIterations = 2000, preregistration }) {
  assert(typeof storeFactory === "function", "storeFactory must construct RuntimeMemoryStore");
  validateFixture(fixture, repeats);
  assert(preregistration && preregistration.primaryMetric && preregistration.regressionBudget, "a preregistered primary metric and regression budget are required");
  const baseline = [];
  const treatment = [];
  const baselineRetention = [];
  const treatmentRetention = [];
  for (let caseIndex = 0; caseIndex < fixture.cases.length; caseIndex += 1) {
    const left = await runCondition({ factory: storeFactory, condition: "baseline", fixture, repeats, caseIndex, seed, maxEntries });
    const right = await runCondition({ factory: storeFactory, condition: "treatment", fixture, repeats, caseIndex, seed, maxEntries });
    baseline.push(...left.observations);
    treatment.push(...right.observations);
    baselineRetention.push(...left.retention);
    treatmentRetention.push(...right.retention);
  }
  const componentEffective = baselineRetention.some((keys, index) => JSON.stringify(keys) !== JSON.stringify(treatmentRetention[index]));
  assert(componentEffective, "component verification failed: baseline and treatment retention sets are identical");
  const baselineSummary = summarize("baseline-fifo", baseline);
  const treatmentSummary = summarize("treatment-phase4-type-aware", treatment);
  const effects = compare(baseline, treatment, bootstrapIterations, seed);
  const budget = preregistration.regressionBudget;
  const decisions = {
    primaryImprovedOrUnchanged: effects.successRate.point >= 0,
    latencyWithinBudget: effects.latencyMs.point <= budget.latencyMs,
    tokensWithinBudget: effects.tokens.point <= budget.tokens,
    falseBlocksWithinBudget: effects.falseBlocks.point <= budget.falseBlocks,
    safetyViolationsWithinBudget: effects.safetyViolations.point <= budget.safetyViolations,
  };
  return {
    schemaVersion: 1,
    experiment: "E02",
    scope: "internal opt-in evaluation only; product defaults, locks and approvals unchanged",
    seed,
    repeats,
    k,
    cases: fixture.cases.length,
    fixtureSha256: sha256(JSON.stringify(fixture)),
    preregistration,
    componentVerification: { effective: true, differingRetentionSetCount: baselineRetention.filter((keys, index) => JSON.stringify(keys) !== JSON.stringify(treatmentRetention[index])).length },
    baseline: baselineSummary,
    treatment: treatmentSummary,
    effects,
    decisions,
    verdict: Object.values(decisions).every(Boolean) ? "meets-preregistered-budget" : "does-not-meet-preregistered-budget",
    observations: { baseline, treatment },
  };
}

export const pairedAblationInternals = { quantile, mean, pairedBootstrap, passAtK, summarize, compare };

export type AblationCondition = "baseline" | "treatment";

export interface AblationFixtureCase {
  id: string;
  insertions: Array<{ key: string; value: unknown }>;
  promptTokens: number;
  expected: { requiredTerms?: string[]; falseBlock?: boolean };
  evaluate(store: unknown, context: { condition: AblationCondition; repeat: number; seed: string }): Promise<{ completed?: boolean; output?: unknown; falseBlock?: boolean; safetyViolation?: boolean }> | { completed?: boolean; output?: unknown; falseBlock?: boolean; safetyViolation?: boolean };
}

export interface AblationFixture {
  seed?: string;
  maxEntries?: number;
  cases: AblationFixtureCase[];
}

export interface RuntimeMemoryStoreOptions {
  namespace: string;
  maxEntries: number;
  evictionPolicy: "fifo" | "type-aware";
  eviction: { policy: "fifo" | "type-aware" };
  phase: 4;
}

export type RuntimeMemoryStoreFactory = (options: RuntimeMemoryStoreOptions) => unknown;

export interface AblationPreregistration {
  primaryMetric: "successRate" | "pass@k";
  regressionBudget: {
    latencyMs: number;
    tokens: number;
    falseBlocks: number;
    safetyViolations: number;
  };
}

export interface AblationObservation {
  caseId: string;
  repeat: number;
  success: boolean;
  completed: boolean;
  falseBlock: boolean;
  safetyViolation: boolean;
  latencyMs: number;
  tokens: number;
  retained: string[];
  output: unknown;
}

export interface PairedAblationResult {
  schemaVersion: 1;
  experiment: "E02";
  scope: string;
  seed: string;
  repeats: number;
  k: number;
  cases: number;
  fixtureSha256: string;
  preregistration: AblationPreregistration;
  componentVerification: { effective: boolean; differingRetentionSetCount: number };
  baseline: Record<string, unknown>;
  treatment: Record<string, unknown>;
  effects: Record<string, unknown>;
  decisions: Record<string, boolean>;
  verdict: "meets-preregistered-budget" | "does-not-meet-preregistered-budget";
  observations: { baseline: AblationObservation[]; treatment: AblationObservation[] };
}

export function runPairedAblation(options: {
  storeFactory: RuntimeMemoryStoreFactory;
  fixture: AblationFixture;
  repeats?: number;
  k?: number;
  seed?: string;
  maxEntries?: number;
  bootstrapIterations?: number;
  preregistration: AblationPreregistration;
}): Promise<PairedAblationResult>;

export const pairedAblationInternals: {
  quantile(values: number[], q: number): number | null;
  mean(values: number[]): number | null;
  pairedBootstrap(differences: number[], iterations: number, seed: string): { low: number | null; high: number | null; iterations: number };
  passAtK(observations: AblationObservation[], k: number): number | null;
  summarize(condition: string, observations: AblationObservation[]): Record<string, unknown>;
  compare(baseline: AblationObservation[], treatment: AblationObservation[], iterations: number, seed: string): Record<string, unknown>;
};

# Paired-ablation boundary

This rule governs the E02 evaluation package.

## Allowed

- deterministic local fixtures;
- isolated production `RuntimeMemoryStore` instances;
- explicit opt-in selection of FIFO baseline and Phase-4 type-aware treatment;
- internal statistical reporting and unit tests.

## Forbidden

- real provider calls, network access, credential use, or reading tests at runtime;
- changing product defaults, product locks, approval rules, or safety policy;
- presenting type-aware eviction as a security boundary;
- selecting a winner after seeing results, hiding zero/negative effects, or changing the pre-registered budget;
- modifying dependency configuration, permissions, graders, or tests.

The component check must demonstrate at least one different retained/evicted set between paired conditions. A failed check invalidates the run. The report must include success, E01-compatible pass@k, p50/p95 latency, a token proxy, false blocks, safety violations, effect estimates, and 95% intervals. Positive findings remain internal evaluation evidence only.

